# ruff: noqa: E501
from fastapi import APIRouter
from fastapi.responses import HTMLResponse

router = APIRouter(tags=["web"])

APP_HTML = """<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI Software Company</title>
<style>
:root{font-family:Inter,system-ui,sans-serif;color:#eef2ff;background:#070b18}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at top right,#1c2450,#070b18 48%);min-height:100vh}.shell{max-width:1200px;margin:auto;padding:28px}.top{display:flex;justify-content:space-between;gap:20px;align-items:center}.brand{font-size:26px;font-weight:800}.muted{color:#9aa5c1}.grid{display:grid;grid-template-columns:1.35fr .65fr;gap:18px;margin-top:22px}.card{background:#10162a;border:1px solid #252e4a;border-radius:18px;padding:20px;box-shadow:0 18px 50px #0004}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.stat{padding:16px;border-radius:14px;background:#151d35}.stat b{display:block;font-size:24px;margin-top:6px}.stack{display:grid;gap:12px}label{display:grid;gap:7px;color:#aeb8d0;font-size:13px}input,textarea{width:100%;border:1px solid #303b5d;background:#0b1020;color:#fff;border-radius:10px;padding:11px;font:inherit}textarea{min-height:100px;resize:vertical}button{border:0;border-radius:10px;padding:11px 16px;background:#5b6cff;color:#fff;font-weight:700;cursor:pointer}button.secondary{background:#252e4a}.row{display:flex;gap:10px;align-items:center}.pill{padding:5px 9px;border-radius:999px;background:#1c2847;color:#aebeff;font-size:12px}.mission{display:flex;justify-content:space-between;gap:16px;padding:13px 0;border-bottom:1px solid #222b43}.events{max-height:330px;overflow:auto;font-size:13px}.event{padding:10px 0;border-bottom:1px solid #20283d}@media(max-width:800px){.grid{grid-template-columns:1fr}.stats{grid-template-columns:repeat(2,1fr)}.top{align-items:flex-start;flex-direction:column}}
</style></head><body><main class="shell">
<div class="top"><div><div class="brand">AI Software Company</div><div class="muted">Company control center · human direction, autonomous execution</div></div><span id="status" class="pill">loading</span></div>
<section class="card" style="margin-top:18px"><div class="stats"><div class="stat">Projects<b id="projects">0</b></div><div class="stat">Tasks<b id="tasks">0</b></div><div class="stat">Agents<b id="agents">0</b></div><div class="stat">Company<b id="companyStatus">idle</b></div></div></section>
<div class="grid"><section class="card"><h2>Give the company a mission</h2><p class="muted">Submit the human-level objective. Routine orchestration stays inside the company backend.</p><form id="missionForm" class="stack"><label>Mission name<input id="name" required maxlength="200" placeholder="Build an AI research assistant"></label><label>Objective<textarea id="objective" required maxlength="5000" placeholder="Describe the outcome you want."></textarea></label><button type="submit">Start mission</button></form><p id="message" class="muted"></p></section>
<section class="card"><div class="row" style="justify-content:space-between"><h2>Human control</h2><button id="stop" class="secondary">Stop company</button></div><p class="muted">Emergency control is exposed separately from normal mission execution.</p></section></div>
<div class="grid"><section class="card"><h2>Mission history</h2><div id="missions" class="stack"><span class="muted">No missions yet.</span></div></section><section class="card"><h2>Execution events</h2><div id="events" class="events"><span class="muted">No events yet.</span></div></section></div><section class="card" style="margin-top:18px"><h2 id="auditMission">Mission details</h2><div id="outputs" class="events"><span class="muted">Select a mission.</span></div><div id="audit" class="events" style="margin-top:12px"><span class="muted">No audit entries.</span></div></section>
</main><script>
const $=id=>document.getElementById(id);async function get(path){const r=await fetch(path);if(!r.ok)throw new Error(await r.text());return r.json()}function escapeHtml(v){return String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}async function showOutputs(id){try{const rows=await get('/api/missions/'+encodeURIComponent(id)+'/outputs');$('outputs').innerHTML=rows.length?rows.map(o=>'<div class="event"><div class="row"><b>'+escapeHtml(o.name)+'</b><span class="pill">'+escapeHtml(o.status)+'</span></div><div class="muted">'+escapeHtml(o.output_type)+'</div>'+(o.repository?'<div class="muted">Repository: '+escapeHtml(o.repository)+'</div>':'')+'</div>').join(''):'<span class="muted">No project outputs recorded.</span>'}catch(e){$('outputs').innerHTML='<span class="muted">'+escapeHtml(e.message)+'</span>'}}
async function showAudit(id,name){$('auditMission').textContent=name;try{const rows=await get('/api/missions/'+encodeURIComponent(id)+'/audit');$('audit').innerHTML=rows.length?rows.map(a=>'<div class="event"><div class="row"><b>'+escapeHtml(a.event_type)+'</b><span class="pill">'+escapeHtml(a.status||'event')+'</span></div><div class="muted">'+escapeHtml(a.message)+'</div><div class="muted">'+escapeHtml(new Date(a.timestamp).toLocaleString())+'</div></div>').join(''):'<span class="muted">No audit entries.</span>'}catch(e){$('audit').innerHTML='<span class="muted">'+escapeHtml(e.message)+'</span>'}}
async function refresh(){try{const [state,missions,events,summary]=await Promise.all([get('/api/company/state'),get('/api/missions'),get('/api/company/events'),get('/dashboard/summary')]);$('status').textContent=state.status;$('companyStatus').textContent=state.status;$('projects').textContent=summary.projects;$('tasks').textContent=summary.tasks;$('agents').textContent=summary.agents;$('missions').innerHTML=missions.length?missions.map(m=>'<button class="mission" style="text-align:left;background:transparent;color:inherit;border-radius:0" onclick="showAudit(\''+m.mission.id+'\',\''+escapeHtml(m.mission.name).replace(/'/g,'&#39;')+'\');showOutputs(\''+m.mission.id+'\')"><div><b>'+escapeHtml(m.mission.name)+'</b><div class="muted">'+escapeHtml(m.mission.objective)+'</div></div><span class="pill">'+m.status+'</span></button>').join(''):'<span class="muted">No missions yet.</span>';$('events').innerHTML=events.length?events.slice().reverse().map(e=>'<div class="event"><b>'+escapeHtml(e.event_type)+'</b><div class="muted">'+escapeHtml(e.payload?.message||e.project_id||'company event')+'</div></div>').join(''):'<span class="muted">No events yet.</span>'}catch(e){$('message').textContent=e.message}}$('missionForm').addEventListener('submit',async e=>{e.preventDefault();const button=$('missionForm').querySelector('button[type="submit"]');button.disabled=true;$('message').textContent='Starting mission…';try{const r=await fetch('/api/missions',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:$('name').value.trim(),objective:$('objective').value.trim()})});let data={};try{data=await r.json()}catch{}if(!r.ok)throw new Error(data.detail||('Mission request failed ('+r.status+')'));const id=data.mission?.id;if(!id)throw new Error('Mission was accepted but no mission ID was returned.');$('message').textContent='Mission accepted. Starting the factory…';$('missionForm').reset();const factory=await fetch('/api/missions/'+encodeURIComponent(id)+'/factory-run',{method:'POST'});let factoryData={};try{factoryData=await factory.json()}catch{}if(!factory.ok)throw new Error(factoryData.detail||('Factory start failed ('+factory.status+')'));$('message').textContent='Factory started. Tracking mission…';await refresh();await trackMission(id)}catch(error){$('message').textContent=error instanceof Error?error.message:'Unable to start mission.'}finally{button.disabled=false}});async function trackMission(id){for(let i=0;i<60;i++){try{const job=await get('/api/missions/'+encodeURIComponent(id)+'/job');$('message').textContent=job.message||('Mission status: '+job.status);await refresh();if(['completed','blocked','failed','cancelled'].includes(job.status))return}catch{}await new Promise(resolve=>setTimeout(resolve,2000))}}$('stop').addEventListener('click',async()=>{try{const r=await fetch('/api/company/stop',{method:'POST'});if(!r.ok)throw new Error(await r.text());$('message').textContent='Company stopped.';await refresh()}catch(error){$('message').textContent=error instanceof Error?error.message:'Unable to stop company.'}});refresh();setInterval(refresh,3000);
</script></body></html>"""


@router.get("/app", response_class=HTMLResponse)
async def company_app() -> HTMLResponse:
    return HTMLResponse(APP_HTML)
